#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream ss(markdown);

    // Convert the markdown text to HTML
    std::string html;
    ss >> html;

    return html;
}

int main() {
    std::string markdown = "# My Heading\n\nThis is a simple paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

